            { kind: "fill", promptUk: "Допишіть значення для програмного фокуса на заголовку без додаткової зупинки Tab", promptEn: "Fill in the value for programmatic focus on a heading without adding a Tab stop", language: "html", code: "<h2 tabindex=\"___\">Confirm order</h2>", accepted: ["-1"], caseSensitive: true, explanationUk: "tabindex=-1 дозволяє програмно встановити фокус, не додаючи заголовок до послідовного Tab.", explanationEn: "tabindex=-1 permits programmatic focus without adding the heading to the sequential Tab order." },
            { kind: "read", promptUk: "Для чого tabindex=\"-1\" на заголовку щойно відкритої модалки?", promptEn: "What is tabindex=\"-1\" on the heading of a just-opened modal for?", language: "html", code: "<h2 id=\"dlg-title\" tabindex=\"-1\">Confirm</h2>", options: ["щоб скрипт міг перевести фокус, не ставлячи заголовок у цикл Tab", "щоб заголовок став третьою точкою табуляції", "це заборонено WCAG", "щоб прибрати видимий фокус"], optionsEn: ["A script can move focus there without adding the heading to the Tab sequence", "To make the heading the third Tab stop", "WCAG forbids it", "To remove the visible focus indicator"], correctIndex: 0, explanationUk: "Програмний фокус.", explanationEn: "Programmatic focus." },
            { kind: "mcq", promptUk: "Чи стає div із role=button і tabindex=0 повноцінною кнопкою автоматично?", promptEn: "Does a div with role=button and tabindex=0 automatically become a fully functional button?", options: ["Ні: потрібна також клавіатурна поведінка та стан; зазвичай краще використати button", "Так: ARIA автоматично додає Enter і Space", "Так: tabindex додає обробник кліку", "Ні: кнопки не можуть отримувати фокус"], optionsEn: ["No: keyboard behavior and state must also be implemented; a native button is usually better", "Yes: ARIA automatically adds Enter and Space", "Yes: tabindex adds a click handler", "No: buttons cannot receive focus"], correctIndex: 0, explanationUk: "ARIA описує семантику, але не додає нативну поведінку клавіатури.", explanationEn: "ARIA supplies semantics but does not add native keyboard behavior." }
