            { kind: "read", promptUk: "Чому модалка без пастки фокуса вважається зламаною?", promptEn: "Why is a modal without a focus trap considered broken?", language: "html", code: "<!-- Tab moves to the page behind the overlay -->", options: ["Tab іде на сторінку під оверлеєм, яку не видно; користувач губить контекст", "пастка заборонена WCAG завжди", "Escape тоді не працює з іншої причини", "skip-посилання заміняє пастку"], optionsEn: ["Tab can move to the obscured page behind the overlay and users lose context", "A focus trap is always forbidden by WCAG", "Escape stops working for a different reason", "A skip link replaces focus containment"], correctIndex: 0, explanationUk: "Фокус лишається в відкритому діалозі.", explanationEn: "Focus stays in the open dialog." },
            { kind: "mcq", promptUk: "Діалог видалив рядок разом із кнопкою, що його відкрила. Куди спрямувати фокус після закриття?", promptEn: "A dialog deleted the row containing its opener. Where should focus go after closing?", options: ["На логічний доступний елемент наступного кроку, наприклад сусідній рядок або заголовок списку", "На видалену кнопку незалежно від її існування", "Завжди на body без повідомлення", "На випадкове посилання футера"], optionsEn: ["To an appropriate available next element, such as an adjacent row or the list heading", "To the deleted button regardless of whether it exists", "Always to the body without context", "To a random footer link"], correctIndex: 0, explanationUk: "Коли відкривача немає, фокус повертають у логічне місце робочого процесу.", explanationEn: "When the opener is gone, restore focus to a logical place in the workflow." }
